580	+/// Returns `(versions, pruned_cids)` where `pruned_cids` contains CIDs of
581	+/// versions that exceeded `max_versions` and should be unpinned.
582	+pub fn apply_versioning(
583	+    existing_versions: Option<Vec<cipherbox_core::folder::VersionEntry>>,
584	+    old_file_cid: &Option<String>,
585	+    old_encrypted_key: &str,
586	+    old_iv: &str,
587	+    old_size: u64,
588	+    old_mode: &str,
589	+    now_ms: u64,
590	+    max_versions: usize,
591	+    cooldown_ms: u64,
592	+    ino: u64,
593	+) -> (Option<Vec<cipherbox_core::folder::VersionEntry>>, Vec<String>) {
594	+    let should_version = if let Some(ref versions) = existing_versions {
595	+        if let Some(newest) = versions.first() {
596	+            now_ms.saturating_sub(newest.timestamp) >= cooldown_ms
597	+        } else {
598	+            old_file_cid.as_ref().is_some_and(|c| !c.is_empty())
599	+        }
600	+    } else {
601	+        old_file_cid.as_ref().is_some_and(|c| !c.is_empty())
602	+    };
603	+
604	+    if !should_version {
605	+        if existing_versions.is_some() {
606	+            log::debug!("Version cooldown active for ino {} -- skipping version creation", ino);
607	+        }
608	+        return (existing_versions, vec![]);
609	+    }
610	+
611	+    match old_file_cid {
612	+        Some(ref old_c) if !old_c.is_empty() => {
613	+            let version_entry = cipherbox_core::folder::VersionEntry {
614	+                cid: old_c.clone(),
615	+                file_key_encrypted: old_encrypted_key.to_string(),
616	+                file_iv: old_iv.to_string(),
617	+                size: old_size,
618	+                timestamp: now_ms,
619	+                encryption_mode: old_mode.to_string(),
620	+            };
621	+            let mut versions = vec![version_entry];
622	+            versions.extend(existing_versions.unwrap_or_default());
623	+            let pruned: Vec<String> = if versions.len() > max_versions {
624	+                versions.split_off(max_versions).into_iter().map(|v| v.cid).collect()
